```cpp
#include <string>
#include <iostream>
#include <regex>

std::string convert_markdown_to_html(const std::string& markdown) {
    // Create a regular expression to match all Markdown syntax characters
    const std::regex markdown_syntex{"([\\*~_\\()\\[\\]#\\+\\-\\>\\!\\|\\\\\ ?])|(^\\s*[-*\\+]\\s)|(^\\s*[1-9]$)|(^\\s*$)"};

    // Create a regular expression to match all HTML syntax characters
    const std::regex html_syntax{"([<>«»¡¿\\(\\)\\[\\]\\{\\}\\?\\*\\~\\-|\\\\\ \\!\\+\\=])"};

    // Use a lambda function to replace all Markdown syntax characters with their HTML equivalent
    auto markdown_to_html_converter = [](const std::string& match_str) {
        std::string replacement;
        switch (match_str[0]) {
            case '*':
            case '_':
                replacement = "<em>";
                break;
            case '~':
                replacement = "<s>";
                break;
            case '-':
                replacement = "<del>";
                break;
            case '+':
                replacement = "<ins>";
                break;
            case '#':
                replacement = "<h1>";
                break;
            case '>':
                replacement = "<blockquote>";
                break;
            case '!':
                replacement = "<img src=\"";
                break;
            case '\\':
                replacement = "\\";
                break;
            case '?':
                replacement = "<strong>";
                break;
            case '*':
            case '~':
                replacement = "<em>";
                break;
            case '-':
            case '+':
                replacement = "<del><ins>";
                break;
            default:
                replacement = match_str;
                break;
        }
        return replacement + match_str + match_str[match_str.length() - 1] + ">";
    };

    // Use the regular expressions and lambda function to replace Markdown syntax with HTML syntax
    std::string html = std::regex_replace(markdown, markdown_syntex, markdown_to_html_converter);
    html = std::regex_replace(html, html_syntax, std::function<std::string(const std::smatch&)>([](const std::smatch& match) {
        if (match.str(1) == "<") return "&lt;";
        if (match.str(1) == ">") return "&gt;";
        if (match.str(1) == "«") return "&laquo;";
        if (match.str(1) == "»") return "&raquo;";
        if (match.str(1) == "¡") return "&iexcl;";
        if (match.str(1) == "¿") return "&quest;";
        return match.str(1);
    }));

    return html;
}
```
This function can be used as follows:
```cpp
