    std::string markdown = "This is *some* sample **text** with `highlighted` and ***bold*** **formatting**.";
    std::string html = convert_markdown_to_html(markdown);
    std::cout << "Markdown:\n" << markdown << "\n\nHTML:\n" << html << std::endl;
