        // Read the file line by line
        string fileLine;
        while (getline(fileStream, fileLine)) {
            fileLines.push_back(fileLine);
        }

        // Close the file stream
        fileStream.close();

        // Iterate through each line of the file
        for (const string& fileLine : fileLines) {
            // Check if the word is present in the line
            size_t found = fileLine.find(word);
            while (found != string::npos) {
                wordCount++;  // Increment the count if the word is found

                // Find the next occurrence of the word in the line
                found = fileLine.find(word, found + word.length());
            }
        }
    }
    else {
        cout << "Error opening file: " << fileName << endl;
    }

    return wordCount;
